def route(request_id, challenger_pct):
    return 'challenger' if request_id % 100 < challenger_pct else 'champion'

def count_split(n_requests, challenger_pct):
    champ = 0
    chall = 0
    for i in range(n_requests):
        if route(i, challenger_pct) == 'challenger':
            chall += 1
        else:
            champ += 1
    return champ, chall

def report(n_requests, challenger_pct):
    champ, chall = count_split(n_requests, challenger_pct)
    print(f"champion: {champ} requests ({champ / n_requests * 100:.1f}%)")
    print(f"challenger: {chall} requests ({chall / n_requests * 100:.1f}%)")

report(100, 10)
print("after rollout to 50/50:")
report(100, 50)
